const body = $input.all()[0].json.body || {};
const events = body.events || [];

if (events.length === 0) {
  throw new Error('No LINE events');
}

const event = events[0];

if (event.type !== 'message' || (event.message.type !== 'audio' && event.message.type !== 'voice')) {
  return [{ json: { skip: true, reason: 'Not voice/audio message: ' + (event.message?.type || 'unknown') } }];
}

return [{
  json: {
    messageId: event.message.id,
    replyToken: event.replyToken,
    userId: event.source?.userId
  }
}];

const compilerRes = $input.all()[0].json;
const payload = compilerRes.compiled_payload || {};
const replyToken = $('📝 Parse Voice Event').first().json.replyToken;

const textSpoken = payload.text || 'รับทราบคำสั่งเรียบร้อยแล้วค่ะ';
const transcript = compilerRes.transcript || '(no transcript)';
const face = payload.face || 'HAPPY';

const reply = {
  type: 'flex',
  altText: '🎤 Zenbo heard: ' + transcript.substring(0, 60),
  contents: {
    type: 'bubble',
    size: 'kilo',
    header: {
      type: 'box',
      layout: 'vertical',
      backgroundColor: '#7C3AED',
      contents: [{
        type: 'text',
        text: '🎤 Voice → IntelSphere',
        weight: 'bold',
        color: '#FFFFFF',
        size: 'md'
      }]
    },
    body: {
      type: 'box',
      layout: 'vertical',
      spacing: 'md',
      contents: [
        { type: 'text', text: '🎧 ได้ยิน: "' + transcript + '"', size: 'xs', color: '#64748B', wrap: true },
        { type: 'separator', margin: 'sm' },
        { type: 'text', text: '🗣️ ' + textSpoken, size: 'sm', weight: 'bold', color: '#1E293B', wrap: true },
        { type: 'text', text: '😊 ' + face + ' | ✅ Done', size: 'xs', color: '#10B981', margin: 'md' }
      ]
    }
  }
};

return [{ json: { replyToken: replyToken, replyPayload: reply } }];
